        if (Sys.Helpers.IsEmpty(signatureId)) {
            Log.Verbose("No signature id to reset");
        }
        else {
            Data.SetValue("SignatureId__", "");
            Data.SetValue("SignatureExpirationDateTime__", null);
            Lib.P2P.Docusign.DeleteTransaction("DocusignEnvelope");
