																		"contractStatusTag__": {
																			"type": "HTML",
																			"data": false,
																			"stamp": 13,
																			"options": {
																				"label": "contractStatusTag__",
																				"htmlContent": "<input id=\"onLoadContractStatus\" type=\"hidden\" style=\"display:none;\" onclick=\"SetStatus(event);\">\n<div id=\"contractStatus\" class=\"text-size-M\"><span></span></div>\n<div id=\"contractTerminationContainer\" class=\"Text\" style=\"display: flex;\">\n\t<div id=\"contractTermination\" onclick=\"OnClick();\" class=\"text-size-MS text-color-color1\" style=\"cursor: pointer;text-decoration: underline;\"><span></span></div>\n\t<i class=\"fa fa-exclamation-circle fa-lg text-color-color3\" style=\"margin-left: 5px;padding-top: 3px;\"></i>\n</div>\n<script type=\"text/javascript\">\n\twindow.postMessage({ eventName: \"onLoadContractStatus\", control: \"ContractStatusTag__\" }, document.location.origin);\n\tfunction SetStatus(evt)\n\t{\n\t\tvar contractStatusContainer = document.getElementById(\"contractStatus\");\n\t\tvar contractTerminationContainer = document.getElementById(\"contractTerminationContainer\");\n\t\tvar contractTermination = document.getElementById(\"contractTermination\");\n\t\tvar statusClass = \"text-color-\" + evt.color;\n\n\t\tcontractStatusContainer.querySelector('span').innerHTML =  evt.statusLabel;\n\t\tcontractStatusContainer.classList.add(statusClass);\n\t\tif(evt.terminationStatus === \"\")\n\t\t{\n\t\t\tcontractTerminationContainer.style.display = \"none\"\n\t\t}\n\t\telse\n\t\t{\n\t\t\tcontractTermination.querySelector('span').innerHTML =  evt.terminationStatus;\n\t\t}\n\t}\n\n\tfunction OnClick()\n\t{\n\t\twindow.postMessage({ eventName: \"onClick\", control: \"contractStatusTag__\"}, document.location.origin);\n\t}\n</script>",
																				"css": "@ #contractStatus {\n\tdisplay: list-item;\n\tlist-style-type: disc;\n\tlist-style-position: inside;\n}@ \n\n#contractStatus span {\n\tposition: relative;\n\tleft: -10px\n}@ ",
